cd /home/admin/backend && php artisan tinker --no-interaction << 'EOF'
// 統計 schedules 表中 start_time 格式分佈
echo "=== start_time 格式分佈（代課記錄）===\n";
$rows = \Illuminate\Support\Facades\DB::select("
  SELECT
    LENGTH(start_time) AS len,
    LEFT(start_time, 5) AS sample,
    COUNT(*) AS cnt
  FROM schedules
  WHERE status = 'scheduled'
    AND original_schedule_id IS NOT NULL
  GROUP BY LENGTH(start_time), LEFT(start_time, 5)
  ORDER BY cnt DESC
");
foreach ($rows as $r) echo json_encode($r, JSON_UNESCAPED_UNICODE) . PHP_EOL;

// 找出所有 HH:MM:SS 格式的代課記錄（join 會失敗的）
echo "\n=== HH:MM:SS 格式（join 失效的代課記錄）===\n";
$bad = \Illuminate\Support\Facades\DB::select("
  SELECT s.id, s.student_course_id, DATE(s.schedule_date) AS sched_date,
    s.start_time, s.teacher_id, u.Name AS sub_teacher
  FROM schedules s
  LEFT JOIN User u ON u.id = s.teacher_id
  WHERE s.status = 'scheduled'
    AND s.original_schedule_id IS NOT NULL
    AND LENGTH(s.start_time) > 5
");
foreach ($bad as $r) echo json_encode($r, JSON_UNESCAPED_UNICODE) . PHP_EOL;
echo "共 " . count($bad) . " 筆 join 失效的代課記錄\n";
EOF
